const catNorm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleUpperCase('es-PE').replace(/\s+/g,' ').trim();
const catKey=s=>catNorm(s).replace(/[^A-Z0-9]/g,'');
const catAlias=(k,s)=>catKey(k==='clientes'?catNorm(s).replace(/^(LA|EL|LAS|LOS)\s+/,''):s);
function catCanonical(k,s){
 const list=catalogs[k]||[],key=catKey(s);
 if(!key)return '';
 const same=list.find(x=>catKey(x)===key);
 if(same)return same;
 if(k==='clientes'){
  const alias=catAlias(k,s),matches=list.filter(x=>catAlias(k,x)===alias);
  if(matches.length===1)return matches[0];
 }
 return '';
}
function catDistance(x,y,threshold=2){
 if(Math.abs(x.length-y.length)>threshold)return threshold+1;
 let prev=Array.from({length:y.length+1},(_,i)=>i);
 for(let i=1;i<=x.length;i++){
  const next=[i];
  for(let j=1;j<=y.length;j++)next[j]=Math.min(next[j-1]+1,prev[j]+1,prev[j-1]+(x[i-1]===y[j-1]?0:1));
  if(Math.min(...next)>threshold)return threshold+1;
  prev=next;
 }
 return prev[y.length];
}
function catCandidates(k,search,max=55){
 const q=catKey(search),a=catAlias(k,search);
 if(!q)return (catalogs[k]||[]).slice(0,max).map(value=>({value,rank:10}));
 const found=new Map();
 for(const value of catalogs[k]||[]){
  const key=catKey(value),alias=catAlias(k,value);
  let rank=999;
  if(key===q)rank=0;
  else if(alias===a)rank=1;
  else if(key.startsWith(q)||alias.startsWith(a))rank=2;
  else if(key.includes(q)||alias.includes(a))rank=3;
  else if(q.length>=4){
   const threshold=q.length>=8?2:1;
   const words=catNorm(value).split(/[^A-Z0-9]+/).filter(x=>x.length>=4);
   if(catDistance(key,q,threshold)<=threshold||words.some(x=>catDistance(x,q,threshold)<=threshold))rank=4;
  }
  if(rank===999)continue;
  const old=found.get(key);
  if(!old||rank<old.rank)found.set(key,{value,rank});
 }
 return [...found.values()].sort((x,y)=>x.rank-y.rank||x.value.localeCompare(y.value,'es')).slice(0,max);
}
function catalogQueue(){try{const q=JSON.parse(localStorage.getItem(CAT_PENDING)||'[]');return Array.isArray(q)?q:[]}catch{return []}}
function addPendingCatalog(k,value){
 if(!CAT_SHARED.includes(k))return;
 const q=catalogQueue();
 if(!q.some(x=>x.kind===k&&catKey(x.value)===catKey(value))){
  q.push({kind:k,value});localStorage.setItem(CAT_PENDING,JSON.stringify(q));
 }
}
function addCatalog(k,v,opts={}){
 v=String(v||'').trim().replace(/\s+/g,' ');
 if(!v||!Array.isArray(catalogs[k]))return false;
 const existing=catCanonical(k,v);
 if(existing)return existing;
 if(opts.checkSimilar){
  const matches=catCandidates(k,v,3);
  if(matches.length&&matches[0].rank<=4){
   if(confirm('Encontramos «'+matches[0].value+'». ¿Quieres usar ese nombre existente?'))return matches[0].value;
   if(!confirm('¿Seguro que «'+v+'» es otro elemento diferente?'))return false;
  }
 }
 catalogs[k].push(v);catalogs[k].sort((x,y)=>x.localeCompare(y,'es'));saveCats();
 if(!opts.noCloud){addPendingCatalog(k,v);window.DibiserCatalogs?.sync?.().catch(()=>{});}
 return v;
}
let syncingCatalog=false,lastCatalogPull=0;
async function syncCatalogs(){
 const cloud=window.DibiserCloud;
 if(syncingCatalog||!cloud?.connected()||!cloud.status().authorized||Date.now()-lastCatalogPull<20000)return;
 syncingCatalog=true;lastCatalogPull=Date.now();
 try{
  const items=await cloud.catalogItems();
  let changed=false;
  if(Array.isArray(items))for(const item of items){
   const k=item?.kind,v=item?.value;
   if(CAT_SHARED.includes(k)&&v&&!catCanonical(k,v)){catalogs[k].push(String(v));changed=true;}
  }
  if(changed){for(const k of CAT_SHARED)catalogs[k].sort((x,y)=>x.localeCompare(y,'es'));saveCats();}
  for(const item of catalogQueue().slice(0,10)){
   await cloud.saveCatalog(item.kind,item.value);
   const queue=catalogQueue().filter(x=>!(x.kind===item.kind&&catKey(x.value)===catKey(item.value)));
   localStorage.setItem(CAT_PENDING,JSON.stringify(queue));
  }
 }catch(err){console.warn('Catálogos pendientes:',err.message)}
 finally{syncingCatalog=false}
}
function catalogNamesFromMovements(records){
 const names={clientes:'cliente',conductores:'conductor',placas:'placa',materiales:'material',maquinarias:'maquinariaTransportada',carretas:'carreta',camasBajas:'camaBaja',trabajos:'trabajo',responsables:'responsable'};
 let changed=false;
 for(const row of records||[]){
  for(const [kind,property] of Object.entries(names)){
   const val=String(row[property]||'').trim();
   if(val&&!catCanonical(kind,val)){
    catalogs[kind].push(val);changed=true;
   }
  }
 }
 if(changed){
  for(const k of Object.keys(names))catalogs[k].sort((x,y)=>x.localeCompare(y,'es'));
  saveCats();
 }
}
window.DibiserCatalogs={sync:syncCatalogs,ingestHistory:catalogNamesFromMovements};
if(!localStorage.getItem(CAT_MIGRATED)){
 for(const k of CAT_SHARED)for(const value of catalogs[k]||[]){
  if(!(INITIAL[k]||[]).some(x=>catKey(x)===catKey(value)))addPendingCatalog(k,value);
 }
 localStorage.setItem(CAT_MIGRATED,'1');
}
